CREATE TYPE "RefundStatus" AS ENUM ('CREATING','PENDING','PROCESSED','FAILED','REVIEW');
CREATE TABLE "Refund" ("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL UNIQUE REFERENCES "Order"("id") ON DELETE RESTRICT ON UPDATE CASCADE,"amountPaise" INTEGER NOT NULL CHECK ("amountPaise">0),"status" "RefundStatus" NOT NULL DEFAULT 'CREATING',"providerRefundId" TEXT UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
